//#region 🔖️Errors
/// 🚨️ Incremental inflate reports its closed syntax and output-limit causes.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DeflateError {
    BadBlockType,
    BadStoredLength,
    BadHuffmanCode,
    BadDistance,
    UnexpectedEnd,
    OutputLimitExceeded,
}
